ALTER SECURITY INTEGRATION my_oauth_int SET ENABLED = TRUE;

ALTER SECURITY INTEGRATION IF EXISTS my_oauth_int SET
    ENABLED = TRUE
    OAUTH_REDIRECT_URI = 'https://example.com/oauth/callback'
    OAUTH_ISSUE_REFRESH_TOKENS = TRUE
    OAUTH_REFRESH_TOKEN_VALIDITY = 86400
    OAUTH_USE_SECONDARY_ROLES = NONE
    ALLOWED_ROLES_LIST = ('my_analyst_role')
    BLOCKED_ROLES_LIST = ('ACCOUNTADMIN', 'SECURITYADMIN')
    NETWORK_POLICY = 'my_network_policy'
    COMMENT = 'custom oauth client';

ALTER SECURITY INTEGRATION my_oauth_int SET TAG my_tag = 'tag_value';

ALTER SECURITY INTEGRATION my_oauth_int UNSET TAG my_tag;

ALTER SECURITY INTEGRATION IF EXISTS my_oauth_int UNSET ENABLED, NETWORK_POLICY;

ALTER SECURITY INTEGRATION my_oauth_int UNSET COMMENT;
